<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Notification Preferences</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0f172a;
      --card: #111827;
      --card-border: #263449;
      --text: #f8fafc;
      --muted: #b7c2d4;
      --accent: #8b5cf6;
      --accent-strong: #a78bfa;
      --focus: #22d3ee;
      --error: #fca5a5;
      --shadow: 0 24px 70px rgba(0, 0, 0, 0.45);
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      display: grid;
      place-items: center;
      padding: 2rem;
      background:
        radial-gradient(circle at top left, rgba(139, 92, 246, 0.24), transparent 34rem),
        radial-gradient(circle at bottom right, rgba(34, 211, 238, 0.14), transparent 30rem),
        var(--bg);
      color: var(--text);
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      line-height: 1.5;
    }

    main {
      width: min(100%, 32rem);
    }

    .form-card {
      padding: clamp(1.5rem, 4vw, 2.25rem);
      border: 1px solid var(--card-border);
      border-radius: 1.5rem;
      background: linear-gradient(145deg, rgba(17, 24, 39, 0.96), rgba(15, 23, 42, 0.96));
      box-shadow: var(--shadow);
    }

    h1 {
      margin: 0 0 0.5rem;
      font-size: clamp(1.7rem, 5vw, 2.35rem);
      line-height: 1.1;
    }

    .intro {
      margin: 0 0 1.75rem;
      color: var(--muted);
    }

    .form-field {
      margin: 0 0 1.5rem;
    }

    fieldset {
      margin: 0;
      padding: 0;
      border: 0;
    }

    legend {
      margin-bottom: 1rem;
      font-size: 1.05rem;
      font-weight: 700;
    }

    .required {
      color: var(--accent-strong);
    }

    .choices {
      display: grid;
      gap: 0.85rem;
    }

    .choice {
      display: flex;
      align-items: center;
      gap: 0.85rem;
      padding: 1rem;
      border: 1px solid var(--card-border);
      border-radius: 1rem;
      background: rgba(15, 23, 42, 0.72);
      color: var(--text);
      cursor: pointer;
      transition: border-color 160ms ease, background 160ms ease, transform 160ms ease;
    }

    .choice:hover {
      border-color: rgba(167, 139, 250, 0.72);
      background: rgba(30, 41, 59, 0.88);
      transform: translateY(-1px);
    }

    input[type="radio"] {
      width: 1.15rem;
      height: 1.15rem;
      margin: 0;
      accent-color: var(--accent);
      flex: 0 0 auto;
    }

    input[type="radio"]:focus-visible {
      outline: 3px solid var(--focus);
      outline-offset: 3px;
    }

    button {
      width: 100%;
      border: 0;
      border-radius: 999px;
      padding: 0.95rem 1.25rem;
      background: linear-gradient(135deg, var(--accent), #06b6d4);
      color: #ffffff;
      font: inherit;
      font-weight: 800;
      cursor: pointer;
      box-shadow: 0 14px 34px rgba(139, 92, 246, 0.32);
      transition: transform 160ms ease, box-shadow 160ms ease;
    }

    button:hover {
      transform: translateY(-1px);
      box-shadow: 0 18px 42px rgba(139, 92, 246, 0.38);
    }

    button:focus-visible {
      outline: 3px solid var(--focus);
      outline-offset: 4px;
    }

    .message {
      min-height: 1.5rem;
      margin: 1rem 0 0;
      color: var(--muted);
      font-weight: 600;
    }

    .message.error {
      color: var(--error);
    }
  </style>
</head>
<body>
  <main>
    <form class="form-card" id="notification-form">
      <h1>Notification Preferences</h1>
      <p class="intro">Choose how you would like us to contact you with important updates.</p>

      <div class="form-field">
        <fieldset>
          <legend>How do you prefer to receive notifications? <span class="required" aria-label="required">*</span></legend>
          <div class="choices">
            <label class="choice" for="email">
              <input type="radio" id="email" name="notificationPreference" value="Email" required>
              <span>Email</span>
            </label>

            <label class="choice" for="sms">
              <input type="radio" id="sms" name="notificationPreference" value="SMS">
              <span>SMS</span>
            </label>

            <label class="choice" for="push">
              <input type="radio" id="push" name="notificationPreference" value="Push Notifications">
              <span>Push Notifications</span>
            </label>
          </div>
        </fieldset>
      </div>

      <button type="submit">Submit preference</button>
      <p class="message" id="form-message" role="status" aria-live="polite"></p>
    </form>
  </main>

  <script>
    const form = document.querySelector("#notification-form");
    const message = document.querySelector("#form-message");

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const selectedPreference = new FormData(form).get("notificationPreference");

      if (!selectedPreference) {
        message.textContent = "Please choose one notification option before submitting.";
        message.classList.add("error");
        return;
      }

      message.textContent = `Preference saved: ${selectedPreference}.`;
      message.classList.remove("error");
    });
  </script>
</body>
</html>
